-- Users and expense claims (#21, docs/design/23-users-and-expenses.md §5).
-- Generated by `prisma migrate diff` (the enum, the tables, the indexes and the foreign keys), then
-- the guards added by hand at the end (Prisma leaves CHECK constraints, functions and triggers alone
-- when it diffs the schema). A claim and a payment are the sub-ledger of 未払金〔立替精算〕: their
-- entries are in the ledger, so they follow its rules (02-accounting-rules §1):
--
-- 1. expense_claim and expense_payment cannot be deleted nor truncated (logical delete only: a
--    claim is voided, a payment cancelled, each with a reversal of its entry).
-- 2. After the submission a claim's body (claimant, date, amount, account, tax, segment, partner,
--    description, document, accrual entry, author) never changes: only status, payment_id,
--    void_reason, voided_at, reversal_entry_id and updated_at do. The status moves only
--    submitted -> paid -> submitted (支払の取消) and submitted -> void; a void claim never changes.
-- 3. A payment's body never changes; only its cancellation (cancelled_at, cancel_reason,
--    reversal_entry_id) is set, once.
-- 4. CHECK: positive amounts, the state columns agree with the status.

-- CreateEnum
CREATE TYPE "expense_claim_status" AS ENUM ('submitted', 'paid', 'void');

-- AlterEnum
ALTER TYPE "source_kind" ADD VALUE 'expense';

-- CreateTable
CREATE TABLE "expense_claim" (
    "id" TEXT NOT NULL,
    "claimant_id" TEXT NOT NULL,
    "spent_on" DATE NOT NULL,
    "amount" BIGINT NOT NULL,
    "account_id" TEXT NOT NULL,
    "tax_category_code" TEXT NOT NULL,
    "segment_id" TEXT,
    "partner_id" TEXT,
    "description" TEXT NOT NULL,
    "document_id" TEXT,
    "status" "expense_claim_status" NOT NULL DEFAULT 'submitted',
    "journal_entry_id" TEXT NOT NULL,
    "payment_id" TEXT,
    "void_reason" TEXT,
    "voided_at" TIMESTAMPTZ(6),
    "reversal_entry_id" TEXT,
    "created_by" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,

    CONSTRAINT "expense_claim_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "expense_payment" (
    "id" TEXT NOT NULL,
    "claimant_id" TEXT NOT NULL,
    "paid_on" DATE NOT NULL,
    "wallet_id" TEXT NOT NULL,
    "wallet_transaction_id" TEXT,
    "amount" BIGINT NOT NULL,
    "journal_entry_id" TEXT NOT NULL,
    "cancelled_at" TIMESTAMPTZ(6),
    "cancel_reason" TEXT,
    "reversal_entry_id" TEXT,
    "created_by" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "expense_payment_pkey" PRIMARY KEY ("id")
);

