-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------

ALTER TABLE "expense_claim"
  ADD CONSTRAINT "expense_claim_amount_positive" CHECK ("amount" > 0),
  ADD CONSTRAINT "expense_claim_description_present" CHECK (btrim("description") <> ''),
  -- 支払済み ⇔ the payment in force is set.
  ADD CONSTRAINT "expense_claim_paid_fields" CHECK (("status" = 'paid') = ("payment_id" IS NOT NULL)),
  -- 取消済み ⇔ voided_at; a void claim has its reason; the reversal only on a void claim.
  ADD CONSTRAINT "expense_claim_void_fields" CHECK (
    ("status" = 'void') = ("voided_at" IS NOT NULL)
    AND ("status" <> 'void' OR "void_reason" IS NOT NULL)
    AND ("reversal_entry_id" IS NULL OR "status" = 'void')
  );

ALTER TABLE "expense_payment"
  ADD CONSTRAINT "expense_payment_amount_positive" CHECK ("amount" > 0),
  -- A cancellation has its reason; the reversal only on a cancelled payment.
  ADD CONSTRAINT "expense_payment_cancel_fields" CHECK (
    ("cancelled_at" IS NULL) = ("cancel_reason" IS NULL)
    AND ("reversal_entry_id" IS NULL OR "cancelled_at" IS NOT NULL)
  );

-- ---------------------------------------------------------------------------
-- expense_claim: no DELETE; after the submission only the state columns change
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_expense_claim_guard"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ledger guard: expense_claim % cannot be deleted (void it instead)', OLD."id";
  END IF;

  IF OLD."status" = 'void' THEN
    IF to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
      RAISE EXCEPTION 'ledger guard: expense_claim % is void and cannot change', OLD."id";
    END IF;
    RETURN NEW;
  END IF;

  IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
       (OLD."status" = 'submitted' AND NEW."status" IN ('paid', 'void'))
    OR (OLD."status" = 'paid' AND NEW."status" = 'submitted')
  ) THEN
    RAISE EXCEPTION 'ledger guard: expense_claim % cannot go from % to %',
      OLD."id", OLD."status", NEW."status";
  END IF;

  -- Deny by default: every column except the state columns must stay as it is.
  IF (to_jsonb(NEW) - 'status' - 'payment_id' - 'void_reason' - 'voided_at' - 'reversal_entry_id'
        - 'updated_at')
     IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'payment_id' - 'void_reason' - 'voided_at'
        - 'reversal_entry_id' - 'updated_at') THEN
    RAISE EXCEPTION 'ledger guard: expense_claim % was submitted; its body is immutable (only status, payment_id, void_reason, voided_at and reversal_entry_id may change)',
      OLD."id";
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "expense_claim_guard"
  BEFORE UPDATE OR DELETE ON "expense_claim"
  FOR EACH ROW EXECUTE FUNCTION "ledger_expense_claim_guard"();

CREATE TRIGGER "expense_claim_reject_truncate"
  BEFORE TRUNCATE ON "expense_claim"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();

-- ---------------------------------------------------------------------------
-- expense_payment: no DELETE; only the cancellation is set, once
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_expense_payment_guard"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ledger guard: expense_payment % cannot be deleted (cancel it instead)', OLD."id";
  END IF;

  IF OLD."cancelled_at" IS NOT NULL THEN
    IF to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
      RAISE EXCEPTION 'ledger guard: expense_payment % is cancelled and cannot change', OLD."id";
    END IF;
    RETURN NEW;
  END IF;

  IF (to_jsonb(NEW) - 'cancelled_at' - 'cancel_reason' - 'reversal_entry_id')
     IS DISTINCT FROM (to_jsonb(OLD) - 'cancelled_at' - 'cancel_reason' - 'reversal_entry_id') THEN
    RAISE EXCEPTION 'ledger guard: expense_payment % is immutable (only its cancellation may be set)',
      OLD."id";
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "expense_payment_guard"
  BEFORE UPDATE OR DELETE ON "expense_payment"
  FOR EACH ROW EXECUTE FUNCTION "ledger_expense_payment_guard"();

CREATE TRIGGER "expense_payment_reject_truncate"
  BEFORE TRUNCATE ON "expense_payment"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();
